   231|    items.push({
   232|      id: 'live-password-rejected',
   233|      title: 'Supabase rejected the live password',
   234|      detail: attemptedEmail
   235|        ? `The exact password entered for ${attemptedEmail} was sent to Supabase and rejected there.`
   236|        : 'The exact password entered on this screen was sent to Supabase and rejected there.',
   237|      severity: 'critical',
   238|    });
   239|  }
   240|
   241|  if (failureReason === 'email_not_confirmed') {
   242|    items.push({
   243|      id: 'email-not-confirmed',
   244|      title: 'Email confirmation is incomplete',
   245|      detail: 'Supabase still requires email confirmation for this account before password sign-in can complete.',
   246|      severity: 'critical',
   247|    });
   248|  }
   249|
   250|  if (failureReason === 'service_unavailable') {
   251|    items.push({
   252|      id: 'service-unavailable',
   253|      title: 'Live sign-in is temporarily unavailable',
   254|      detail: 'The direct Supabase login path could not be reached cleanly. Trusted owner recovery or password reset is the safe fallback.',
   255|      severity: 'warning',
   256|    });
   257|  }
   258|
   259|  if (failureReason === 'admin_access_locked') {
   260|    items.push({
   261|      id: 'admin-access-locked',
   262|      title: 'Admin access is temporarily locked',
   263|      detail: getAdminAccessLockMessage(),
   264|      severity: 'critical',
   265|    });
   266|  }
   267|
   268|  if (failureReason === 'rate_limited') {
   269|    items.push({
   270|      id: 'server-rate-limit',
   271|      title: 'Rate limit is active',
   272|      detail: 'Supabase is throttling repeated sign-in attempts right now. Wait briefly before trying again.',
   273|      severity: 'warning',
   274|    });
   275|  }
   276|
   277|  const shouldSurfaceServerRepairBlocker = (
   278|    failureReason === 'service_unavailable'
   279|    || failureReason === 'unknown'
   280|  ) && !ownerRepairReadiness.hasRealServiceRole;
   281|
   282|  if (failureReason === 'invalid_credentials' && !ownerRepairReadiness.hasRealServiceRole) {
   283|    items.push({
   284|      id: 'admin-repair-separate-from-signin',
   285|      title: 'Server repair key is separate from normal sign-in',
   286|      detail: 'This password rejection already came from the live Supabase email/password sign-in path. A missing or bad service-role key did not cause the rejection. That key is only needed for backend admin repair of an existing owner auth account if support must inspect or rewrite it.',
   287|      severity: 'warning',
   288|    });
   289|  }
   290|
   291|  if (shouldSurfaceServerRepairBlocker) {
   292|    buildRepairIssueItems(ownerRepairReadiness)
   293|      .filter((item) => item.tone !== 'success')
   294|      .forEach((item) => {
   295|        items.push({
   296|          id: `owner-repair-${item.id}`,
   297|          title: item.title,
   298|          detail: item.detail,
   299|          severity: item.tone === 'critical' ? 'critical' : 'warning',
   300|        });
   301|      });
   302|  }
   303|
   304|  if (lockedUntilMs > Date.now()) {
   305|    items.push({
   306|      id: 'device-cooldown-active',
   307|      title: 'Device cooldown is active',
   308|      detail: getRateLimitMessage(lockedUntilMs),
   309|      severity: 'warning',
   310|    });
   311|  } else if (failureReason === 'invalid_credentials' && remainingAttempts > 0) {
   312|    items.push({
   313|      id: 'device-cooldown-guard',
   314|      title: 'Local cooldown guard is armed',
   315|      detail: `${remainingAttempts} invalid password attempt${remainingAttempts === 1 ? '' : 's'} remain before this device pauses sign-in for 15 minutes.`,
   316|      severity: 'warning',
   317|    });
   318|  }
   319|
   320|  if (audit?.eligible) {
   321|    items.push({
   322|      id: 'trusted-restore-available',
   323|      title: 'Trusted owner restore is available',
   324|      detail: audit.currentIP
   325|        ? `This verified device can restore owner access now from ${audit.currentIP}.`
   326|        : 'This verified device can restore owner access now without another password entry.',
   327|      severity: 'success',
   328|    });
   329|  }
   330|
   331|  if (audit?.emailMismatch && audit.verifiedEmail) {
   332|    items.push({
   333|      id: 'verified-email-mismatch',
   334|      title: 'The entered owner email is not the verified owner email',
   335|      detail: `This device is anchored to ${audit.verifiedEmail}, not ${(audit.requestedEmail ?? attemptedEmail) || 'the current email'}.`,
   336|      severity: 'critical',
   337|    });
   338|  }
   339|
   340|  if (audit && !audit.eligible) {
   341|    const auditReasons = audit.blockingReasons.length > 0 ? audit.blockingReasons : [audit.message];
   342|    auditReasons.forEach((reason, index) => {
   343|      items.push({
   344|        id: `audit-reason-${index}`,
   345|        title: classifyOwnerAuditSeverity(reason) === 'critical' ? 'Owner restore blocker' : 'Owner restore warning',
   346|        detail: reason,
   347|        severity: classifyOwnerAuditSeverity(reason),
   348|      });
   349|    });
   350|  }
   351|
   352|  if (audit?.subnetMatch && audit.currentIP && audit.storedIP && audit.currentIP !== audit.storedIP) {
   353|    items.push({
   354|      id: 'carrier-subnet-match',
   355|      title: 'Carrier subnet fallback is available',
   356|      detail: `Current network ${audit.currentIP} is different from ${audit.storedIP}, but both still match the same trusted carrier subnet.`,
   357|      severity: 'warning',
   358|    });
   359|  }
   360|
   361|  return dedupeLoginIssues(items);
